from collections import defaultdict

class Node:
    def __init__(self, position):
        self.position = position
        self.neighbors = []

    def add_neighbor(self, neighbor):
        self.neighbors.append(neighbor)

    def __repr__(self):
        return f"Node(position={self.position})"

def a_star(graph, start, goal, heuristic):
    open_list = []  
    closed_list = set()

    start_node = Node(start)
    start_node.cost = 0
    start_node.heuristic = heuristic(start_node.position, goal)
    open_list.append(start_node)

    while open_list:
        current_node = min(open_list, key=lambda node: node.cost + node.heuristic)
        closed_list.add(current_node)

        if current_node.position == goal:
            return reconstruct_path(current_node)

        for neighbor in current_node.neighbors:
            neighbor_node = Node(neighbor)
            neighbor_cost = current_node.cost + 1  # Assuming a cost of 1 for each step

            if neighbor in closed_list:
                continue

            neighbor_node.cost = neighbor_cost
            neighbor_node.heuristic = heuristic(neighbor_node.position, goal)
            neighbor_node.parent = current_node

            if neighbor_node not in open_list:
                open_list.append(neighbor_node)

    return None

def reconstruct_path(node):
    path = []
    while node is not None:
        path.append(node.position)
        node = node.parent
    path.reverse()
    return path

def manhattan_distance(pos1, pos2):
    return abs(pos1[0] - pos2[0]) + abs(pos1[1] - pos2[1])

