start = 'A'
goal = 'D'

# Example heuristic function (Manhattan distance)
def manhattan_heuristic(pos1, goal):
    return manhattan_distance(pos1, goal)

# Run A* search
path = a_star(graph, start, goal, manhattan_heuristic) 

if path:
    print("Path:", path)
else:
    print("No path found.")
